    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val1, uint _val2) public payable {
        bool reverted1;
        bool reverted2;
        bool reverted3;

        c.SetMinSum(_val1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }

        c.SetMinSum(_val2); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }

        c.Initialized(); if (__ESBMC_reverted()) return;

        c.SetMinSum(_val1); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            reverted3 = true;
        } else {
            reverted3 = false;
        }

        assert(!reverted1 && !reverted2 && reverted3 && c.MinSum() == _val2);
    }
    receive() external payable {}
}

