pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _val1, uint256 _val2) internal {
        bool reverted1;
        bool reverted2;
        bool reverted3;
        try c.SetMinSum(_val1) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        try c.SetMinSum(_val2) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(_val1) {
            reverted3 = false;
        } catch {
            reverted3 = true;
        }
        assertTrue(!reverted1 && !reverted2 && reverted3 && c.MinSum() == _val2);
    }

    function testFuzz_run(uint256 _val1, uint256 _val2) public {
        _run(_val1, _val2);
    }

    receive() external payable {}
}
